function enterTradeRepublicValue(id){
  const asset=state.investments.find(a=>a.id===id&&a.kind==='etf'&&a.provider==='Trade Republic');
  if(!asset)return;
  const current=investmentAt(state,id,dNow(),allEvents(state,dNow()));
  const latest=bestObservation(asset.observations||[],dNow());
  const lastBroker=latest?.brokerValue!==undefined?latest:null;
  const date=lastBroker?.brokerAsOf||dNow();
  const form=input('Data rilevazione Trade Republic','date','date',date,`min="${START_DATE}" max="${dNow()}" required`)+
    input('Quote possedute (anche frazioni)','units','number',current?.quantity??latest?.units??'','step="0.00000001" min="0.00000001" required',
      'Copia il numero di azioni/quote dalla sezione Posizione di Trade Republic.')+
    input('Prezzo medio di acquisto (€)','avgPrice','number',current?.averagePrice??latest?.avgPrice??'','step="0.000001" min="0.000001" required')+
    input('Controvalore posizione su Trade Republic (€)','brokerValue','number',lastBroker?.brokerValue??'','step="0.01" min="0" required',
      'Questa è la cifra Totale mostrata da Trade Republic, NON il prezzo del mercato esterno.')+
    input('Rendimento non realizzato (%; facoltativo)','brokerPercent','number',lastBroker?.brokerReportedPct??'','step="0.001" min="-100" max="10000"',
      'Se lo lasci vuoto, sarà calcolato da controvalore / (quote × prezzo medio).')+
    `<div class="full insight"><strong>Come viene usato:</strong> fino a una quotazione esterna di data successiva, il controvalore verificato su Trade Republic prevale sui prezzi di Borsa Italiana/Yahoo, che possono essere differenti perché riferiti al prezzo ultimo e non al bid. I dati restano nel JSON locale, <strong>mai su GitHub</strong>.</div>`;
  modal('Valore verificato · Trade Republic',e(asset.name)+' · riconciliazione con il portafoglio del broker.',form,'Salva dati Trade Republic',fd=>{
    const obsDate=mustDate(fd,'date'),units=mustMoney(fd,'units'),avg=mustMoney(fd,'avgPrice'),value=mustMoney(fd,'brokerValue');
    if(units<=0||avg<=0||value<0)throw Error('Quote e prezzo medio devono essere positivi; controvalore non negativo.');
    const pctRaw=String(fd.get('brokerPercent')??'').trim();
    const pct=pctRaw===''?null:safeNum(pctRaw);
    if(pctRaw!=='' && (pct===null||pct< -100||pct>10000))throw Error('Percentuale Trade Republic non valida.');
    const cost=units*avg;
    const calculatedPct=cost>0?(value/cost-1)*100:null;
    const assignedPct=pct!==null?pct:calculatedPct;
    if(pct!==null&&Math.abs(pct-calculatedPct)>1.0){
      if(!confirm('Il rendimento inserito differisce di oltre 1 punto dal calcolo su quote e prezzo medio. Registrare comunque il dato mostrato da Trade Republic?'))return false;
    }
    const previous=bestObservation(asset.observations||[],obsDate);
    const ob={...previous,date:obsDate,mode:'units',units,avgPrice:avg,
      brokerValue:eurRound(value),brokerAsOf:obsDate,brokerRecordedAt:new Date().toISOString(),
      brokerReportedPct:assignedPct,reportedGain:eurRound(value-cost),reportedGainPct:assignedPct,
      source:'Trade Republic · rilevazione della posizione',
      includedEventIds:allEvents(state,obsDate).filter(z=>z.date===obsDate&&z.type==='investment'&&z.assetId===id).map(z=>z.id)};
    // A broker snapshot is an inventory checkpoint. Future confirmed buys are
    // not included in it and will be handled by the existing event ledger.
    delete ob.value;delete ob.price;delete ob.needsCurrentQuote;
    asset.observations=insertObservation(asset.observations,ob);
    persist();notify('Controvalore Trade Republic verificato. Premi Salva per scrivere il JSON.');
  });
}
